class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        ListNode dummy(0, head);
        ListNode* prev = &dummy;
        ListNode* curr = head;
        while (curr) {
            ListNode* tail = curr;
            int count = 0;
            while (tail && count < k) {
                tail = tail->next;
                ++count;
            }
            if (count < k) break;
            vector<ListNode*> st;
            for (int i = 0; i < k; ++i) {
                st.push_back(curr);
                curr = curr->next;
            }
            while (!st.empty()) {
                prev->next = st.back();
                st.pop_back();
                prev = prev->next;
            }
            prev->next = curr;
        }
        return dummy.next;
    }
};

