class Solution:
    def reverseKGroup(self, head, k):
        dummy = ListNode(0, head)
        prev = dummy
        curr = head
        while curr:
            tail = curr
            count = 0
            while tail and count < k:
                tail = tail.next
                count += 1
            if count < k:
                break
            stack = []
            for _ in range(k):
                stack.append(curr)
                curr = curr.next
            while stack:
                prev.next = stack.pop()
                prev = prev.next
            prev.next = curr
        return dummy.next

