class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head);
        ListNode prev = dummy;
        ListNode curr = head;
        while (curr != null) {
            ListNode tail = curr;
            int count = 0;
            while (tail != null && count < k) {
                tail = tail.next;
                count++;
            }
            if (count < k) break;
            Deque<ListNode> stack = new ArrayDeque<>();
            for (int i = 0; i < k; i++) {
                stack.push(curr);
                curr = curr.next;
            }
            while (!stack.isEmpty()) {
                prev.next = stack.pop();
                prev = prev.next;
            }
            prev.next = curr;
        }
        return dummy.next;
    }
}

